package com.volna.profile_service.controller;import com.volna.profile_service.dto.*;import com.volna.profile_service.security.AuthenticatedUser;import com.volna.profile_service.service.ProfileService;import jakarta.validation.Valid;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/profile")public class ProfileController{private final ProfileService s;public ProfileController(ProfileService s){this.s=s;}@GetMapping public ProfileResponse get(@AuthenticationPrincipal AuthenticatedUser u){return s.get(u.authUserId());}@PutMapping public ProfileResponse update(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody ProfileUpdateRequest q){return s.update(u.authUserId(),q);}}
